    if is_union(typ):
        args = typ.__args__
        return {
            'module': 'typing',
            'qualname': 'Union',
            'elem_types': [type_to_dict(arg) for arg in args],
        }
    if is_generic(typ):
        qualname = qualname_of_generic(typ)
        args = typ.__args__
        d: TypeDict = {
            'module': 'typing',
            'qualname': qualname,
        }
        if args is not None:
            d['elem_types'] = [type_to_dict(arg) for arg in args]
